import { createElement } from "react";
import type { RefCallback } from "react";
import { act, create } from "react-test-renderer";
import { describe, expect, it } from "vitest";
import * as reactEntry from "@motion5/react";
import type { Patch, PatchListener, PatchSource } from "@motion5/react";

const PARENT = "walk/pelvis";
const CHILD = "walk/legL_thigh";

/**
 * The seam this file is red against.
 *
 * `useDerivedDomPatch` and `PatchValues` are not exported yet, and a test that names a member the
 * entry does not declare fails `typecheck` rather than an assertion, which is not failing-first
 * evidence. So the shape is declared here and read off the entry through one cast; the commit that
 * lands the hook deletes this block and imports both names instead.
 */
type PatchValues = Patch["values"];
type PatchDerivation = (
  values: readonly PatchValues[],
) => Readonly<Record<string, unknown>> | undefined;
type DerivedDomPatchSeam = <T extends Element>(
  source: PatchSource,
  nodeIds: readonly string[],
  derive: PatchDerivation,
) => RefCallback<T>;
const { useDerivedDomPatch } = reactEntry as unknown as {
  useDerivedDomPatch: DerivedDomPatchSeam;
};

interface FakeSource extends PatchSource {
  listenerCount(): number;
  publish(patch: Patch): void;
}

// Two nodes in one store, counted across both: what a fan-in binding owes is one subscription per
// source and the release of every one of them.
function createFakeSource(...initial: readonly Patch[]): FakeSource {
  const listeners = new Map<string, Set<PatchListener>>();
  const latest = new Map<string, Patch>(initial.map((entry) => [entry.nodeId, entry] as const));
  return {
    get: (nodeId) => latest.get(nodeId),
    subscribeNode(nodeId, listener) {
      const existing = listeners.get(nodeId) ?? new Set<PatchListener>();
      existing.add(listener);
      listeners.set(nodeId, existing);
      return () => {
        existing.delete(listener);
      };
    },
    listenerCount: () => [...listeners.values()].reduce((total, set) => total + set.size, 0),
    publish(next) {
      latest.set(next.nodeId, next);
      for (const listener of [...(listeners.get(next.nodeId) ?? [])]) listener(next);
    },
  };
}

function patch(
  nodeId: string,
  revision: number,
  values: Readonly<Record<string, unknown>>,
  status: Patch["status"] = "ready",
): Patch {
  return {
    nodeId,
    revision,
    values,
    sourceProgress: 0,
    sourceRevisions: {},
    status,
    diagnostics: [],
  };
}

const endpoints: PatchDerivation = ([parent = {}, child = {}]) => ({
  x1: Number(parent.x ?? 0),
  y1: Number(parent.y ?? 0),
  x2: Number(child.x ?? 0),
  y2: Number(child.y ?? 0),
});

interface FakeStyle extends Record<string, unknown> {
  removeProperty(property: string): void;
}
interface FakeSvgTarget {
  style: FakeStyle;
  ownerSVGElement: null;
  attributes: Map<string, string>;
  setAttribute(name: string, value: string): void;
  removeAttribute(name: string): void;
}

/**
 * Geometry keys are readonly IDL attributes on a real element, so this double answers the attribute
 * channel and declares no `x1` property to assign. `removeProperty` empties rather than deletes,
 * like a real `CSSStyleDeclaration`, so hiding twice resolves to the style channel both times.
 */
function createSvgTarget(): FakeSvgTarget {
  const style: FakeStyle = {
    visibility: undefined,
    removeProperty(property) {
      this[property] = undefined;
    },
  };
  const attributes = new Map<string, string>();
  return {
    style,
    ownerSVGElement: null,
    attributes,
    setAttribute(name, value) {
      attributes.set(name, value);
    },
    removeAttribute(name) {
      attributes.delete(name);
    },
  };
}

function mount(
  source: PatchSource,
  target: FakeSvgTarget,
  nodeIds: readonly string[],
  derive: PatchDerivation = endpoints,
): { renders(): number; unmount(): void } {
  // The assertion the red run fails on. A case that throws "not a function" instead is a failure
  // without being failing-first evidence, and this stays afterwards as the entry's surface check.
  expect(typeof useDerivedDomPatch).toBe("function");
  let renders = 0;
  function Consumer(): ReturnType<typeof createElement> {
    renders += 1;
    // Typed as a real SVG element ref: a consumer binds `<line ref={bind}>` and casts nothing.
    const bind: RefCallback<SVGLineElement> = useDerivedDomPatch<SVGLineElement>(
      source,
      [...nodeIds],
      derive,
    );
    return createElement("line", { ref: bind });
  }
  let renderer: { unmount(): void } | undefined;
  act(() => {
    renderer = create(createElement(Consumer), { createNodeMock: () => target });
  });
  return {
    renders: () => renders,
    unmount: () => {
      renderer?.unmount();
    },
  };
}

describe("useDerivedDomPatch", () => {
  it("writes geometry derived from every source, on mount and on later batches, with no React render", () => {
    const source = createFakeSource(
      patch(PARENT, 1, { x: 10, y: 20 }),
      patch(CHILD, 1, { x: 30, y: 40 }),
    );
    const target = createSvgTarget();
    const mounted = mount(source, target, [PARENT, CHILD]);

    expect(Object.fromEntries(target.attributes)).toEqual({
      x1: "10",
      y1: "20",
      x2: "30",
      y2: "40",
    });
    expect(mounted.renders()).toBe(1);

    act(() => {
      source.publish(patch(CHILD, 2, { x: 33, y: 44 }));
    });
    expect(target.attributes.get("x2")).toBe("33");
    expect(target.attributes.get("y2")).toBe("44");
    expect(mounted.renders()).toBe(1);

    expect(source.listenerCount()).toBe(2);
    act(() => {
      mounted.unmount();
    });
    expect(source.listenerCount()).toBe(0);
  });

  it("hides the target while any source is not live, and derives again when every one is", () => {
    const source = createFakeSource(
      patch(PARENT, 1, { x: 10, y: 20 }),
      patch(CHILD, 1, { x: 30, y: 40 }),
    );
    const target = createSvgTarget();
    const mounted = mount(source, target, [PARENT, CHILD]);
    expect(target.attributes.size).toBe(4);

    act(() => {
      source.publish(patch(CHILD, 2, { x: 99, y: 99 }, "blocked"));
    });
    expect(target.style.visibility).toBe("hidden");
    expect(target.attributes.size).toBe(0);

    act(() => {
      source.publish(patch(CHILD, 3, { x: 35, y: 45 }));
    });
    expect(target.style.visibility).toBeUndefined();
    expect(target.attributes.get("x2")).toBe("35");

    // Twice, because a hide that only works on a target which was never shown works once.
    act(() => {
      source.publish(patch(CHILD, 4, { x: 35, y: 45 }, "destroyed"));
    });
    expect(target.style.visibility).toBe("hidden");
    expect(mounted.renders()).toBe(1);

    act(() => {
      mounted.unmount();
    });
  });

  it("composes a derived pose through the adapter and pivots at the element's own origin", () => {
    const source = createFakeSource(patch(PARENT, 1, { x: 10, y: 20, rotation: 30 }));
    const target = createSvgTarget();
    const visor: PatchDerivation = ([head = {}]) => ({
      x: Number(head.x ?? 0),
      y: Number(head.y ?? 0) + 8,
      rotation: Number(head.rotation ?? 0) + 90,
    });
    const mounted = mount(source, target, [PARENT], visor);

    expect(target.style.transform).toBe("translate3d(10px, 28px, 0px) rotate(120deg)");
    expect(target.style.transformBox).toBe("view-box");
    expect(target.style.transformOrigin).toBe("0px 0px");
    // A pose is not geometry: nothing reached the attribute channel.
    expect(target.attributes.size).toBe(0);

    act(() => {
      mounted.unmount();
    });
  });

  it("keeps one subscription per source across a render that passes a fresh id array", () => {
    const source = createFakeSource(patch(PARENT, 1, { x: 1, y: 2 }));
    let subscribes = 0;
    const counted: PatchSource = {
      get: (nodeId) => source.get(nodeId),
      subscribeNode(nodeId, listener) {
        subscribes += 1;
        return source.subscribeNode(nodeId, listener);
      },
    };
    const target = createSvgTarget();
    expect(typeof useDerivedDomPatch).toBe("function");
    function Consumer(): ReturnType<typeof createElement> {
      const bind = useDerivedDomPatch<SVGLineElement>(counted, [PARENT], endpoints);
      return createElement("line", { ref: bind });
    }
    let renderer:
      | { unmount(): void; update(element: ReturnType<typeof createElement>): void }
      | undefined;
    act(() => {
      renderer = create(createElement(Consumer), { createNodeMock: () => target });
    });
    act(() => {
      renderer?.update(createElement(Consumer));
    });

    expect(subscribes).toBe(1);
    expect(source.listenerCount()).toBe(1);
    act(() => {
      renderer?.unmount();
    });
    expect(source.listenerCount()).toBe(0);
  });
});

import { describe, expect, it } from "vitest";
import { createDomPatchAdapter, type DomTarget } from "../../src/adapters/dom";
import type { Patch } from "../../src/runtime/patch-registry";

const NODE_ID = "walk/legL_thigh";

/**
 * The seam this file is red against: `applyValues` is not declared on `DomPatchAdapter` yet, and a
 * test that names a member the interface does not declare fails `typecheck` rather than an
 * assertion. The commit that lands the member deletes this block and calls it directly.
 */
interface DerivedWriteSeam {
  applyValues(nodeId: string, values: Readonly<Record<string, unknown>>): void;
}
function derived(adapter: unknown): DerivedWriteSeam {
  return adapter as DerivedWriteSeam;
}

function patch(
  revision: number,
  values: Readonly<Record<string, unknown>>,
  status: Patch["status"] = "ready",
): Patch {
  return {
    nodeId: NODE_ID,
    revision,
    values,
    sourceProgress: 0,
    sourceRevisions: {},
    status,
    diagnostics: [],
  };
}

interface FakeStyle extends Record<string, unknown> {
  removeProperty(property: string): void;
}
interface FakeSvgLine extends Record<string, unknown> {
  style: FakeStyle;
  ownerSVGElement: null;
  attributes: Map<string, string>;
  setAttribute(name: string, value: string): void;
  removeAttribute(name: string): void;
  readonly x1: string;
  textContent: string;
}

/**
 * A structural double for an SVG element, and the point of it is what it refuses.
 *
 * `x1` is readable and not writable, exactly like the IDL attribute on `SVGLineElement`, so the
 * property assignment this writer used to make unconditionally throws in a module rather than
 * failing quietly, and the attribute channel is the only one that can carry it. `textContent` keeps
 * a setter, so it stays a property write. `removeProperty` empties rather than deletes, like a real
 * `CSSStyleDeclaration`.
 */
function createSvgLine(): FakeSvgLine {
  const style: FakeStyle = {
    visibility: undefined,
    removeProperty(property) {
      this[property] = undefined;
    },
  };
  const attributes = new Map<string, string>();
  let content = "";
  const line = {
    style,
    ownerSVGElement: null,
    attributes,
    setAttribute(name: string, value: string): void {
      attributes.set(name, value);
    },
    removeAttribute(name: string): void {
      attributes.delete(name);
    },
    get textContent(): string {
      return content;
    },
    set textContent(next: string) {
      content = next;
    },
  };
  Object.defineProperty(line, "x1", {
    enumerable: true,
    get: () => attributes.get("x1") ?? "",
  });
  return line as unknown as FakeSvgLine;
}

function asTarget(line: FakeSvgLine): DomTarget {
  return line as unknown as DomTarget;
}

describe("DOM adapter write channels", () => {
  it("writes a readonly geometry key as an attribute and removes it when a later patch omits it", () => {
    const line = createSvgLine();
    const adapter = createDomPatchAdapter({ style: {} }, undefined, () => asTarget(line));

    // Red on an assertion rather than on an uncaught error: a property assignment to a readonly IDL
    // attribute throws in a module, and the property channel is the only one that used to be left.
    expect(() =>
      adapter.apply(patch(1, { x1: 10, y1: 20, visibility: "hidden", textContent: "L" })),
    ).not.toThrow();
    expect(line.attributes.get("x1")).toBe("10");
    expect(line.attributes.get("y1")).toBe("20");
    expect(line.style.visibility).toBe("hidden");
    expect(line.textContent).toBe("L");

    adapter.apply(patch(2, { x1: 10 }));
    expect(line.attributes.has("y1")).toBe(false);
    expect(line.attributes.get("x1")).toBe("10");
    expect(line.style.visibility).toBeUndefined();
  });

  it("keeps the property channel for a target that answers no attributes at all", () => {
    const plain: { style: Record<string, unknown>; pose?: unknown } = { style: {} };
    const adapter = createDomPatchAdapter({ style: {} }, undefined, () => plain as DomTarget);

    adapter.apply(patch(1, { pose: "3px" }));
    expect(plain.pose).toBe("3px");
  });

  it("writes a derived record through the same diff as a patch, with no status and no revision", () => {
    const written: Array<Readonly<Record<string, unknown>>> = [];
    const line = createSvgLine();
    const adapter = createDomPatchAdapter(
      { style: {} },
      undefined,
      () => asTarget(line),
      (_target, values) => {
        written.push({ ...values });
      },
    );
    expect(typeof derived(adapter).applyValues).toBe("function");

    derived(adapter).applyValues(NODE_ID, { x1: 1 });
    derived(adapter).applyValues(NODE_ID, { x1: 1 });
    adapter.apply(patch(1, { x1: 1 }));
    derived(adapter).applyValues(NODE_ID, { x1: 2 });

    expect(written).toEqual([{ x1: 1 }, { x1: 2 }]);
  });

  it("pins the reference box and a zero origin once, and only on an SVG-shaped target", () => {
    const line = createSvgLine();
    let box: unknown;
    let boxWrites = 0;
    Object.defineProperty(line.style, "transformBox", {
      enumerable: true,
      get: () => box,
      set: (next: unknown) => {
        box = next;
        boxWrites += 1;
      },
    });
    const adapter = createDomPatchAdapter({ style: {} }, undefined, () => asTarget(line));

    adapter.apply(patch(1, { x: 4, y: 8, rotation: 90 }));
    adapter.apply(patch(2, { x: 5, y: 8, rotation: 90 }));
    expect(line.style.transform).toBe("translate3d(5px, 8px, 0px) rotate(90deg)");
    expect(line.style.transformBox).toBe("view-box");
    expect(line.style.transformOrigin).toBe("0px 0px");
    expect(boxWrites).toBe(1);

    const html: { style: Record<string, unknown> } = { style: {} };
    const htmlAdapter = createDomPatchAdapter({ style: {} }, undefined, () => html as DomTarget);
    htmlAdapter.apply(patch(1, { x: 4, y: 8 }));
    expect(html.style.transform).toBe("translate3d(4px, 8px, 0px)");
    expect(html.style.transformBox).toBeUndefined();
    expect(html.style.transformOrigin).toBeUndefined();
  });
});
